#[rustfmt::skip]
pub const TEMPLATE_KEYS: &[&str] = &[
    "plan",
    "report",
    "research",
    "verify",
];

#[rustfmt::skip]
pub fn builtin_workflows() -> &'static [EmbeddedAsset] {
    BUILTIN_WORKFLOWS
}

#[rustfmt::skip]
pub fn bundled_workflows() -> &'static [EmbeddedAsset] {
    BUNDLED_WORKFLOWS
}

#[rustfmt::skip]
pub fn bundled_prompts() -> &'static [EmbeddedAsset] {
    BUNDLED_PROMPTS
}

/// Look up a prompt template by its bare key.
#[rustfmt::skip]
pub fn template(name: &str) -> Option<&'static str> {
    match name {
        "plan" => Some("# Plan template\n\nYou are planning work for the objective below.\n\nObjective: {objective}\n\nReturn a small, independent set of research questions as JSON.\n"),
        "report" => Some("# Report template\n\nObjective: {objective}\n\nVerified claims:\n{claims}\n\nWrite a concise cited report. Keep every citation traceable to a source.\n"),
        "research" => Some("# Research template\n\nObjective: {objective}\n\nResearch question: {question}\n\nReturn structured claims with evidence and sources as JSON.\n"),
        "verify" => Some("# Verify template\n\nObjective: {objective}\n\nCandidate claims:\n{claims}\n\nIndependently verify each claim and return a verdict per claim as JSON.\n"),
        _ => None,
    }
}
